<script setup>
import { ref } from 'vue'
const props=defineProps({label:{type:String,default:'Swipe right to continue'}})
const emit=defineEmits(['complete']);const progress=ref(0),dragging=ref(false),track=ref(null);let startX=0,startProgress=0
function begin(x){dragging.value=true;startX=x;startProgress=progress.value}function move(x){if(!dragging.value||!track.value)return;progress.value=Math.max(0,Math.min(1,startProgress+(x-startX)/Math.max(track.value.clientWidth,1)))}function finish(){if(!dragging.value)return;dragging.value=false;if(progress.value>=.8){progress.value=1;emit('complete');window.setTimeout(()=>{progress.value=0},180)}else progress.value=0}function down(e){if(e.pointerType==='mouse'&&e.button!==0)return;e.currentTarget.setPointerCapture?.(e.pointerId);begin(e.clientX)}function up(e){e.currentTarget.releasePointerCapture?.(e.pointerId);finish()}
</script>
<template><div ref="track" class="swipe-bar" role="slider" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="Math.round(progress*100)" :aria-valuetext="props.label"><div class="swipe-bar__fill" :style="{width:`${progress*100}%`}"></div><span class="swipe-bar__label">{{props.label}}</span><button class="swipe-bar__thumb" type="button" :aria-label="props.label" :style="{left:`calc(${progress*100}% - 24px)`}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="finish">→</button></div></template>
<style scoped>.swipe-bar{position:relative;width:100%;height:56px;overflow:hidden;border:1px solid var(--kfe-ui-border);border-radius:999px;background:var(--kfe-ui-surface-muted,var(--kfe-ui-bg));color:var(--kfe-ui-text);touch-action:none;user-select:none}.swipe-bar__fill{position:absolute;inset:0 auto 0 0;background:var(--kfe-accent-soft);transition:width .08s linear}.swipe-bar__label{position:absolute;inset:0;display:grid;place-items:center;font-size:.82rem;font-weight:850;pointer-events:none}.swipe-bar__thumb{position:absolute;top:4px;width:48px;height:48px;border:0;border-radius:50%;background:var(--kfe-accent);color:#fff;font-size:1.35rem;font-weight:900;touch-action:none;cursor:grab}.swipe-bar__thumb:active{cursor:grabbing}.swipe-bar__thumb:focus-visible{outline:3px solid color-mix(in srgb,var(--kfe-accent) 70%,transparent);outline-offset:2px}</style>
